import uiautomation as auto
auto.SetGlobalSearchTimeout(1)
root=auto.ControlFromHandle(8456336)
def walk(c,depth=0):
    if depth>8: return
    try:
        typ=c.ControlTypeName
        if typ in ("TabItemControl","EditControl","DocumentControl"):
            print(depth,typ,repr(c.Name),repr(c.AutomationId),repr(c.ClassName))
        for k in c.GetChildren():
            walk(k,depth+1)
    except Exception:
        return
walk(root)
